# Verify hypothesis on all demos: crop to marker frame (marker = color with exactly 4 cells,
# forming rectangle corners); keep big blocks; each stray color (singletons / small comps)
# expands to rect of unit size (dominant block dims) placed adjacent to nearest block.
def solve(gi):
    cnt,C_=C(invent(gi)[0])
    bg=C_.most_common(1)[0][0]
    # marker: color with exactly 4 singleton cells (or comp count==1 of 4 cells)
    def comps_all(col):
        seen=set(); H,W=len(gi),len(gi[0]); res=[]
        for i in range(H):
            for j in range(W):
                if gi[i][j]==col and (i,j) not in seen:
                    q=deque([(i,j)]); seen.add((i,j)); cs=[(i,j)]
                    while q:
                        a,b=q.popleft()
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and gi[x][y]==col and (x,y) not in seen:
                                seen.add((x,y)); cs.append((x,y)); q.append((x,y))
                    res.append(cs)
        return res
    mk=None
    for col,cc in C_.items():
        if cc==4 and len(comps_all(col))==1 and len(comps_all(col)[0])==4:
            mk=col;break
    assert mk,'no marker'
    mkp=comps_all(mk)[0]; rs=sorted(p[0] for p in mkp); cl=sorted(p[1] for p in mkp)
    r0,r1,c0,c1=rs[0],rs[-1],cl[0],cl[-1]
    oh,ow=r1-r0+1,c1-c0+1
    out=[[bg]*ow for _ in range(oh)]
    # blocks: comps of non-bg,non-mk with size >= some threshold; strays smaller
    def comps_non(bg,mk,col=None):
        seen=set(); H,W=len(gi),len(gi[0]); res=[]
        for i in range(H):
            for j in range(W):
                v=gi[i][j]
                if v!=bg and v!=mk and (v==col or col is None):
                    if (i,j) in seen: continue
                    q=deque([(i,j)]); seen.add((i,j)); cs=[(i,j)]; colv=v
                    while q:
                        a,b=q.popleft()
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and gi[x][y]==colv and (x,y) not in seen:
                                seen.add((x,y)); cs.append((x,y)); q.append((x,y))
                    res.append((colv,cs))
        return res
    units={}  # per-color: max block size
    blocks=[]
    for col,cs in comps_non(bg,mk):
        sz=len(cs)
        if sz>=4:  # block
            units.setdefault(col,[max(units.get(col,[]))] if False else []).append(sz)
            blocks.append((col,cs))
        else:
            units.setdefault(col,[]).append(sz)
    ub=max(max(sizes) for sizes in units.values()) if units else 1
    # place blocks at relative pos
    for col,cs in blocks:
        rr=[p[0]-r0 for p in cs]; cc_=[p[1]-c0 for p in cs]
        for dr,dc_ in set(zip(rr,cc_)):
            if 0<=dr<oh and 0<=dc_<ow: out[dr][dc_]=col
    # strays: per color, expand to ubxub rect; place adjacent to nearest block
    for col,sz in units:
        if sz>=4: continue
        scs=set(p for _,cs in blocks for p in cs)
        best=(None,None,float('inf'))
        for bcol,bcs in blocks:
            brs=set(p for p in bcs)
            for pa,pb in bcs:
                d=abs(pa-(p[0]))+abs(pb-p[1])
                if d<best[2]: best=(bcol,bcs,d)
        bcol,bcs,_=best
        # side: where stray bbox is relative to nearest block cell
        sr=min(p[0] for p in scs); sg=min(p[1] for p in scs); se=max(p[0] for p in scs); sgm=max(p[1] for p in scs)
        bmin=min(p[0] for p in bcs); bmax=max(p[0] for p in bcs); bminc=min(p[1] for p in bcs); bmaxc=max(p[1] for p in bcs)
        dirs=[]
        if sr<bmin: dirs.append(('up',sr))
        if se>bmax: dirs.append(('down',se))
        if sg<bminc: dirs.append(('left',sg))
        if sgm>bmaxc: dirs.append(('right',sgm))
        if not dirs: continue  # already inside/near? 
        dir_,val=dirs[0]
        rpos,cpos=val
        if dir_=='up': pr,pc_=bmin-ub, min(bminc,bmaxc)- (uw:=?) 
    return out
